// dynamic_schemes.txt を material-color-utilities の TypeScript 実装から生成する。
//
// 上流のテストには 2026 仕様と腕時計の期待値がないため、移植元の実装を実行した結果を期待値にする。
// 移植元のリビジョンは .agents/skills/material-design-3-port/references/material-color-utilities の
// submodule (bd811e4ca2ab94c4ce3cadc89c19b1820b9704b3)。
//
// 生成手順 (リポジトリのルートで実行する):
//   mcu=.agents/skills/material-design-3-port/references/material-color-utilities/typescript
//   out=$(mktemp -d)
//   nix shell nixpkgs#nodejs nixpkgs#typescript -c tsc --ignoreConfig --outDir "$out" \
//     --module es2020 --target es2020 --strict --strictNullChecks false --skipLibCheck \
//     $(find "$mcu" -name '*.ts' ! -name '*_test.ts' | grep -v -e quantize -e score -e image_utils \
//       -e theme_utils -e index.ts -e test_utils)
//   # 一部の import は拡張子を省くため、Node.js の ES モジュールとして読めるように補う
//   grep -rl "from '\." "$out" | xargs sed -i -E "s#from '(\.[^']*[^s])'#from '\1.js'#g"
//   echo '{"type":"module"}' > "$out/package.json"
//   nix shell nixpkgs#nodejs -c node crates/md3-color/tests/fixtures/generate_schemes.mjs "$out" \
//     > crates/md3-color/tests/fixtures/dynamic_schemes.txt

import {pathToFileURL} from 'node:url';
import path from 'node:path';

const root = process.argv[2];
const load = (p) => import(pathToFileURL(path.join(root, p)).href);
const {Hct} = await load('hct/hct.js');
const {DynamicScheme} = await load('dynamiccolor/dynamic_scheme.js');
const {Variant} = await load('dynamiccolor/variant.js');
const {SchemeContent} = await load('scheme/scheme_content.js');
const {SchemeCmf} = await load('scheme/scheme_cmf.js');

// Rust の ColorRole::ALL と同じ順序
const roles = [
  'primaryPaletteKeyColor', 'secondaryPaletteKeyColor', 'tertiaryPaletteKeyColor',
  'neutralPaletteKeyColor', 'neutralVariantPaletteKeyColor', 'errorPaletteKeyColor',
  'background', 'onBackground', 'surface', 'surfaceDim', 'surfaceBright',
  'surfaceContainerLowest', 'surfaceContainerLow', 'surfaceContainer', 'surfaceContainerHigh',
  'surfaceContainerHighest', 'onSurface', 'surfaceVariant', 'onSurfaceVariant', 'inverseSurface',
  'inverseOnSurface', 'outline', 'outlineVariant', 'shadow', 'scrim', 'surfaceTint',
  'primary', 'primaryDim', 'onPrimary', 'primaryContainer', 'onPrimaryContainer', 'inversePrimary',
  'secondary', 'secondaryDim', 'onSecondary', 'secondaryContainer', 'onSecondaryContainer',
  'tertiary', 'tertiaryDim', 'onTertiary', 'tertiaryContainer', 'onTertiaryContainer',
  'error', 'errorDim', 'onError', 'errorContainer', 'onErrorContainer',
  'primaryFixed', 'primaryFixedDim', 'onPrimaryFixed', 'onPrimaryFixedVariant',
  'secondaryFixed', 'secondaryFixedDim', 'onSecondaryFixed', 'onSecondaryFixedVariant',
  'tertiaryFixed', 'tertiaryFixedDim', 'onTertiaryFixed', 'onTertiaryFixedVariant',
];

// 紫、赤 (エラーの色相の区間)、シアン、好まれにくい黄、青、低彩度の灰
const seeds = [0xff6750a4, 0xffd32f2f, 0xff009688, 0xff8d8d00, 0xff1e88e5, 0xff6f7a73];
const contrasts = [-1, -0.5, 0, 0.5, 1];
const variantNames = {
  [Variant.MONOCHROME]: 'monochrome', [Variant.NEUTRAL]: 'neutral',
  [Variant.TONAL_SPOT]: 'tonal_spot', [Variant.VIBRANT]: 'vibrant',
  [Variant.EXPRESSIVE]: 'expressive', [Variant.FIDELITY]: 'fidelity',
  [Variant.CONTENT]: 'content', [Variant.RAINBOW]: 'rainbow',
  [Variant.FRUIT_SALAD]: 'fruit_salad', [Variant.CMF]: 'cmf',
};
const hex = (argb) => (argb >>> 0).toString(16).padStart(8, '0');

// [variant, 要求する仕様, 機器]。2025 仕様の要求は、2025 仕様の規則がある組み合わせだけを含める
const configs = [];
for (const v of [Variant.MONOCHROME, Variant.NEUTRAL, Variant.TONAL_SPOT, Variant.VIBRANT,
                 Variant.EXPRESSIVE, Variant.FIDELITY, Variant.CONTENT, Variant.RAINBOW,
                 Variant.FRUIT_SALAD]) {
  configs.push([v, '2021', 'phone']);
}
for (const v of [Variant.NEUTRAL, Variant.TONAL_SPOT, Variant.VIBRANT, Variant.EXPRESSIVE]) {
  configs.push([v, '2025', 'phone']);
  configs.push([v, '2025', 'watch']);
}
configs.push([Variant.CONTENT, '2025', 'watch']);

console.log('# generated by generate_schemes.mjs; columns: ' + roles.join(' '));

function emit(variant, spec, platform, isDark, contrast, sources, scheme) {
  const values = roles.map((r) => hex(scheme[r]).slice(2));
  console.log([variantNames[variant], spec, platform, isDark ? 'dark' : 'light', contrast,
               sources.map(hex).join(','), ':', ...values].join(' '));
}

for (const seed of seeds) {
  for (const [variant, spec, platform] of configs) {
    for (const isDark of [false, true]) {
      for (const contrast of contrasts) {
        const scheme = new DynamicScheme({
          sourceColorHct: Hct.fromInt(seed), variant, contrastLevel: contrast, isDark,
          platform, specVersion: spec,
        });
        emit(variant, spec, platform, isDark, contrast, [seed], scheme);
      }
    }
  }
}

// 2 色目の元の色を使う配色。2 色目は seeds の次の色
seeds.forEach((seed, i) => {
  const second = seeds[(i + 1) % seeds.length];
  for (const isDark of [false, true]) {
    for (const contrast of contrasts) {
      for (const platform of ['phone', 'watch']) {
        for (const sources of [[seed], [seed, second]]) {
          const scheme = new SchemeCmf(sources.map((c) => Hct.fromInt(c)), isDark, contrast,
                                       '2026', platform);
          emit(Variant.CMF, '2026', platform, isDark, contrast, sources, scheme);
        }
      }
      for (const spec of ['2021', '2025']) {
        const sources = [seed, second];
        const scheme = new SchemeContent(sources.map((c) => Hct.fromInt(c)), isDark, contrast,
                                         spec, 'watch');
        emit(Variant.CONTENT, spec, 'watch', isDark, contrast, sources, scheme);
      }
    }
  }
});
